// The browser extension (extensions/chrome/redact.js) must redact exactly like the server (lib/browser-redact.js): both
// scrub the same captured requests, DOM and recordings, so a rule that is tighter on one side than the other either
// leaks a secret or drops useful data. The extension copy is generated by scripts/sync-extension-redact.js. This test
// fails if the generated files are out of date, and checks the extension copy against the canonical vectors directly.
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');

const ROOT = path.join(__dirname, '..');
const CANONICAL = path.join(ROOT, 'test', 'fixtures', 'browser-redact-vectors.json');
const EXT = path.join(ROOT, 'extensions', 'chrome', 'redact.js');

test('the generated extension redaction files are in sync with lib/browser-redact.js', () => {
  execFileSync(process.execPath, [path.join(ROOT, 'scripts', 'sync-extension-redact.js'), '--check'], { stdio: 'pipe' });
});

test('the extension redaction matches the canonical vectors the server uses', async () => {
  const { redact, headers, url } = await import(EXT);
  const v = JSON.parse(fs.readFileSync(CANONICAL, 'utf8'));
  for (const e of v.keys || []) {
    const out = redact({ [e.name]: e.value });
    assert.equal(out[e.name] !== e.value, !!e.secret, `key ${e.name}=${JSON.stringify(e.value)} -> ${JSON.stringify(out[e.name])}`);
  }
  for (const e of v.headers || []) assert.deepEqual(headers(e.in), e.out, `headers ${JSON.stringify(e.in)}`);
  for (const e of v.urls || []) assert.deepEqual(url(e.in), e.out, `url ${e.in}`);
  for (const e of v.json || []) assert.deepEqual(redact(e.in), e.out, `json ${JSON.stringify(e.in)}`);
});
